// CSD_RATIONALE_BEGIN
// Attempt 61 (best: 53.3% accuracy, 99% syntax): 137/300 failures are
// syntax-valid semantic mismatches. The model stops generating after minimal
// complete SQL (e.g., "SELECT col FROM table") and emits EOS, missing
// WHERE / GROUP BY / HAVING / JOIN clauses the question requires.
//
// RegenerateUnitOnGroundingFailure handles identifier grounding and achieves
// 99% syntax; the accuracy gap is structural clause selection. The model
// accepts EOS the moment the SQL grammar sees a complete sentence, even if
// that sentence doesn't answer the question.
//
// Targeted improvements over attempt 61:
//   1. Rewrite AppendTaskGuidance with explicit clause-selection rules keyed
//      to question keywords: aggregation → GROUP BY+HAVING; multi-table →
//      JOIN; conditions → WHERE; ordering → ORDER BY; unique → DISTINCT.
//      Concise, pattern-based phrasing is used to stay within the 4B model's
//      effective attention span.
//   2. Cap sqlBudget at 400 steps (≈512s) to prevent the 1 wall-clock timeout
//      observed in attempt 61 (sqlBudget ≈ 893 → 1143s potential max).
//   3. Keep RegenerateUnitOnGroundingFailure(maxRetries=5, maxRollbackBudget=50)
//      unchanged — it is the source of the 99% syntax.
//   4. Identical preamble/close structure to attempt 61.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 (parser_validity):
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
// Phase 1 preamble: Loop guard !insideConstrainedOut makes the implication
//   vacuous throughout. The only true-flip is on RenderedEndsWith; we
//   simultaneously set currentConstrainedOut := [], and IsValidPrefix([])
//   holds by the method precondition. EOS break leaves insideConstrainedOut
//   false, implication vacuously true.
//
// Phase 2 OpenConstrainedSpan: Only runs when !insideConstrainedOut.
//   Postcondition sets currentConstrainedOut := []; IsValidPrefix([]) holds
//   by precondition. Afterward insideConstrainedOut is true.
//
// Phase 3 RegenerateUnitOnGroundingFailure: Postcondition guarantees
//   resultConstrained is always parser-valid. Assignment
//   currentConstrainedOut := resultConstrained re-establishes the invariant.
//   insideConstrainedOut stays true from Phase 2 (or was true on entry).
//
// Phase 4a CloseConstrainedSpan: Sets insideConstrainedOut := false, making
//   the implication vacuously true; clears currentConstrainedOut := [].
//
// Phase 4b CloseSpanWithinBudget: Postcondition directly guarantees
//   insideOut ==> parser.IsValidPrefix(currentOut).
//
// Invariant 2 (progress): |generated| <= |generatedPrefix| + steps
//
// Phase 1: UnconstrainedStep increments steps by 1 and appends at most 1
//   token (0 for EOS, 1 for non-EOS). Invariant preserved each iteration.
//
// Phase 2: OpenConstrainedSpan appends exactly 1 "<<" token; steps += 1.
//   Net 1:1. Invariant preserved.
//
// Phase 3: stablePrefix = generated[..|generated| - |currentConstrainedOut|].
//   After: generated = stablePrefix + resultConstrained.
//   |generated| = |stablePrefix| + |resultConstrained|
//             <= (|old_generated| - |currentConstrainedOut|)
//                + (|currentConstrainedOut| + sqlBudget)
//             = |old_generated| + sqlBudget
//             <= |generatedPrefix| + old_steps + sqlBudget
//             = |generatedPrefix| + new_steps.
//   Cost contract of RegenerateUnitOnGroundingFailure: at most sqlBudget
//   token-steps, each producing at most 1 visible token. Rejected/rolled-back
//   tokens consume budget without contributing to resultConstrained length.
//
// Phase 4a: CloseConstrainedSpan +1 step, appends at most 1 ">>" token.
// Phase 4b: CloseSpanWithinBudget postcondition |generatedOut| <= |generated|
//   + closeBudget; steps += closeBudget. Invariant preserved transitively.
// CSD_PROOF_SKETCH_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm, "Spider text-to-SQL benchmark. Output: SQL: <<QUERY>>. QUERY must be COMPLETE. Clause rules: (1) aggregation words (most, least, count, total, average, sum, min, max, number of, more than, fewer than) -> use COUNT/SUM/AVG/MIN/MAX plus GROUP BY column plus HAVING condition; (2) multiple entities or tables -> JOIN each table ON condition; (3) filter or condition words -> WHERE clause; (4) ranked or ordered results -> ORDER BY column ASC/DESC; (5) unique or distinct values -> SELECT DISTINCT. Use ONLY exact table and column names from the provided schema. Do not stop generating after a bare SELECT...FROM without all required clauses.");

var steps: nat := 0;

// Phase 1: Short unconstrained preamble (up to 5 steps) to emit "SQL: <<" naturally
while steps < maxSteps && steps < 5 && !insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if next == eosToken {
    break;
  } else {
    generated := generated + [next];
    if RenderedEndsWith(generated, "<<") {
      insideConstrainedOut := true;
      currentConstrainedOut := [];
    }
  }
}

// Phase 2: Force "<<" if not already inside constrained span
if !insideConstrainedOut && steps < maxSteps {
  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;
}

// Phase 3: Schema-grounded constrained SQL generation
// Budget capped at 400 to prevent wall-clock timeout (400 * 1.28s ≈ 512s < 600s limit)
if insideConstrainedOut && steps < maxSteps {
  var remaining := maxSteps - steps;
  if remaining >= 2 {
    var rawBudget := remaining - 1; // reserve 1 step for closing delimiter
    var sqlBudget: nat;
    if rawBudget <= 400 {
      sqlBudget := rawBudget;
    } else {
      sqlBudget := 400;
    }
    var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
    var resultConstrained := helpers.RegenerateUnitOnGroundingFailure(
      lm, parser, constrainedPrompt, currentConstrainedOut, eosToken, sqlBudget, 5, 50
    );
    var stablePrefix := generated[..|generated| - |currentConstrainedOut|];
    generated := stablePrefix + resultConstrained;
    currentConstrainedOut := resultConstrained;
    steps := steps + sqlBudget;
  }
}

// Phase 4: Close the constrained span
if insideConstrainedOut && steps < maxSteps {
  if parser.IsCompletePrefix(currentConstrainedOut) {
    var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + 1;
  } else {
    var remaining := maxSteps - steps;
    var closeBudget: nat;
    if remaining <= 80 {
      closeBudget := remaining;
    } else {
      closeBudget := 80;
    }
    var cg, ci, cc := helpers.CloseSpanWithinBudget(
      lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
    );
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + closeBudget;
  }
}

cost := steps;

